import math

def softmax(values):
    peak = max(values)
    weights = [math.exp(v-peak) for v in values]
    return [w/sum(weights) for w in weights]

def norm(x, eps=1e-5):
    mean = sum(x)/len(x)
    variance = sum((v-mean)**2 for v in x)/len(x)
    return [(v-mean)/math.sqrt(variance+eps) for v in x]

def attend(q, keys, values):
    weights = softmax([sum(a*b for a,b in zip(q,k))/math.sqrt(len(q)) for k in keys])
    return [sum(w*v[j] for w,v in zip(weights,values)) for j in range(len(values[0]))]

def affine(x, weights, bias):
    return [sum(x[i]*weights[i][j] for i in range(len(x)))+bias[j] for j in range(len(bias))]

class Solution:
    def train_step(self, logits: list[list[float]], pairs: list[list[int]], rate: float) -> list[list[float]]:
        gradient=[[0.0]*len(logits[0]) for _ in logits]
        for previous,target in pairs:
            probabilities=softmax(logits[previous])
            for j,p in enumerate(probabilities):
                gradient[previous][j]+=(p-(1 if j==target else 0))/len(pairs)
        return [[v-rate*g for v,g in zip(row,grad)] for row,grad in zip(logits,gradient)]

